window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":6,"chapter":2,"section":"2.1","type":"单选","topic":"操作系统类型","title":"实时、分布式与通用操作系统按目标区分","trigger":"题目综合辨析操作系统安全、分布式系统、实时响应和后台服务。","conclusion":"操作系统负责资源管理、任务调度、接口与安全等多方面工作；实时系统强调在规定期限内响应，分布式系统协调多台计算机资源。","points":["安全不仅防止非法用户访问，还包括认证、授权、隔离、审计和完整性保护。","服务或后台进程可为系统与应用提供持续功能。","分布式操作系统试图把多台计算机的资源统一协调和呈现。","统信UOS桌面专业版基于Linux内核，提供图形桌面、应用运行和系统服务；银河麒麟有面向日常办公的桌面版，以及面向数据中心的服务器版等产品。","HarmonyOS强调多设备应用体验与按设备适配，可涉及手机、平板、智慧屏等终端；这是应用场景和协作能力的特点，不意味着所有设备运行完全相同的软件包。","教学示例：准备在国产桌面系统上完成办公任务，应先核对电脑CPU架构、系统版本及办公软件适配，再从官方渠道安装对应版本并测试文档和外设。","操作系统是系统软件：向下协调CPU、内存、设备和文件等资源，向上提供用户接口与程序可调用的服务。用图形界面启动记事本时，记事本负责编辑，操作系统负责安排运行、分配内存和访问文件；不能把二者当成同一层软件。","课堂按五类归纳：处理机管理安排进程运行；存储管理分配、保护和回收内存；设备管理通过驱动等机制协调输入输出；文件管理组织外存上的文件及其访问；作业管理组织用户提交任务的执行。用户接口用于交互，程序接口供应用请求服务；这些功能相互配合，不是五个互不联系的应用。","按作业处理方式可区分批处理、分时、实时；按支持的用户和任务数又可说单用户/多用户、单任务/多任务。因此实时系统也可以是多任务系统。Windows 10属于支持多用户账户、多任务的图形界面操作系统；多用户不表示普通桌面版允许任意多个用户同时远程交互登录。","网络操作系统提供网络通信、共享及管理等服务；分布式系统进一步协调多台计算机的资源；嵌入式系统面向设备内的特定任务，如控制设备运行。这些是用途或组织方式，不应和单任务/多任务排成一个只能选其一的分类表。"],"boundary":"“实时”强调可预测的时限，不只是平均速度快；操作系统安全也不能缩成单一访问限制。","id":"y2024q6","sources":[{"year":2024,"q":6,"type":"单选"}],"keys":["2024-6"],"related":[{"id":"merged-2","label":"系统软件与应用软件按功能区分","reason":"按资源管理与提供运行环境的功能判断，能说明操作系统为何属于系统软件。"},{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"实时和分布式描述系统目标，并发、共享等描述运行现象，两组概念不能混用。"},{"id":"y2025q7","label":"比较批处理、分时与实时","reason":"按操作对象区分机制，再核对结果和限制。"}],"pointGroups":[{"title":"操作系统的地位、功能与分类","indices":[6,7,8,9]},{"title":"系统服务与组织方式","indices":[0,1,2]},{"title":"认识国产系统时同时看用途与适配范围","indices":[3,4,5]}],"pointPresentation":{"6":{"title":"操作系统在硬件和应用之间","navigationLabel":"操作系统在硬件和应用之间"},"7":{"title":"五类管理功能分别管理什么","navigationLabel":"五类管理功能分别管理什么"},"8":{"title":"先看分类维度，再判断能否并存","navigationLabel":"先看分类维度，再判断能否并存"},"9":{"title":"网络、分布式与嵌入式的侧重点","navigationLabel":"网络、分布式与嵌入式的侧重点"}},"comparison":{"headers":["判断维度","示例","不要混成"],"rows":[["管理对象","处理机、内存、设备、文件、作业","某一个普通应用"],["处理方式","批处理、分时、实时","用户数量"],["用户与任务数","单/多用户、单/多任务","实时或网络的反义词"],["用途和组织","网络、分布式、嵌入式","只能三选一的全部分类"]]}},{"q":44,"target":null,"chapter":2,"section":"2.1","topic":"程序与进程","title":"程序是静态代码，进程是一次运行实例","conclusion":"进程是程序在一定数据集上的一次执行过程，也是系统管理运行活动的重要抽象。","points":["同一程序可产生多个进程，每个进程有自己的运行状态、进程标识符PID和资源。教学示例：分别启动两个传统记事本实例，可得到两个PID；关闭其中一个，另一实例及磁盘上的notepad.exe仍可存在。","任务管理器可查看当前进程及CPU、内存占用。一个应用可能包含多个进程，一个进程也可能有多个窗口，因此不能把任务栏按钮数、窗口数、进程数机械地视为相等。","结束一个进程不等于卸载程序；未保存的数据可能丢失。"],"boundary":"进程process不是泛指的处理processing，也不等同于磁盘上的可执行文件。","type":"填空","trigger":"从程序与进程的判断与应用整理。","id":"y2022q44","sources":[{"year":2022,"q":44,"type":"填空"}],"keys":["2022-44"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"在任务管理器中观察或结束一次运行实例，可具体理解进程与程序文件的区别。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"结束进程只停止运行，卸载才移除软件主体；两类操作各自保留的内容不同。"}],"pointGroups":[{"title":"程序文件与运行实例","indices":[0]},{"title":"怎样观察和结束进程","indices":[1,2]}]},{"q":5,"chapter":2,"section":"2.1","type":"单选","topic":"操作系统特征","title":"并发、共享、虚拟和异步描述不同操作系统现象","trigger":"真题从多任务、资源共享、逻辑映射和事件发生次序考查操作系统特征。","conclusion":"多任务在一段时间内共同推进体现并发；共同使用资源体现共享；物理资源映射为逻辑资源体现虚拟；运行次序受调度影响体现异步。","points":["单核可通过轮流分配短暂运行时间，让多个任务在一段时间内共同推进，这叫并发；多个处理核心可在同一时刻执行不同任务，体现并行。教学示例：边听音乐边编辑文档，不足以单独证明两个任务正同时占用不同核心。","共享是多个任务共同使用资源，必要时要互斥、同步和调度。教学示例：多个程序把作业交给同一台打印机，系统通过队列协调先后，并不让纸张上的内容任意混印。","异步性指任务的推进速度与先后受调度和I/O完成时间等影响，不是完全预定的时间序列。某任务等待磁盘读写时，系统可以先运行其他可运行任务；这不表示程序内部的因果关系失效。","Windows可让多个任务在一段时间内共同推进；虚拟内存利用地址映射扩展可用的逻辑空间，但仍受地址空间、提交限制和可用存储等约束。"],"boundary":"并发不等于同一时刻并行；异步也不等于结果任意或系统没有确定规则。","id":"y2026q7","sources":[{"year":2023,"q":5,"type":"单选"},{"year":2026,"q":7,"type":"单选"},{"year":2021,"q":4,"type":"单选","page":2}],"keys":["2023-5","2026-7","2021-4"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"并发调度作用于运行中的进程，先区分静态程序和运行实例。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"单核时间片可并发，多核才可能同时并行；不能把核数直接相加成时钟频率。"},{"id":"y2025q7","label":"批处理系统的典型短板是交互性差","reason":"多道批处理让多个作业交替使用资源，是并发与共享的具体应用。"}],"pointGroups":[{"title":"并发、并行与资源共享","indices":[0,1]},{"title":"异步推进和虚拟内存","indices":[2,3]}]},{"q":7,"chapter":2,"section":"2.1","type":"单选","topic":"批处理系统","title":"批处理系统的典型短板是交互性差","trigger":"题目要求识别批处理操作系统的缺点。","conclusion":"批处理系统将作业成批提交并自动连续处理，吞吐量较高，但用户难以及时干预，交互性较差。","points":["批处理可减少人工装卸和处理器空闲时间。","多道批处理可让多个作业共同驻留内存并交替使用资源。","交互式任务更适合分时系统。","批处理适合成批提交、较少交互的作业，重点是吞吐和资源利用；分时把处理机时间分配给多个交互任务，使用户获得及时响应；实时系统重点是在规定期限内响应与完成相关处理，如工业控制。批处理交互性差，不等于不能执行I/O。","批量夜间结算看重成批完成，多个用户交互操作看重分时响应，控制设备必须按时响应看重实时性。“平均算得快”不能保证每次都赶上期限；实时也不要求CPU永远空闲。2024年第6题“要求过高”带评价色彩，学习时应采用“有规定时限”的机制，不把该用词当作技术定义。"],"boundary":"批处理并非不能处理I/O，也不等于不支持多任务；应抓住“提交后等待结果”的交互特征。","id":"y2025q7","sources":[{"year":2025,"q":7,"type":"单选"}],"keys":["2025-7"],"related":[{"id":"y2026q7","label":"并发、共享、虚拟和异步描述不同操作系统现象","reason":"多道批处理中的作业交替推进体现并发，并不要求所有作业同一时刻执行。"},{"id":"y2024q6","label":"实时、分布式与通用操作系统按目标区分","reason":"选操作系统要先看目标：高吞吐、及时交互和规定期限内响应是不同需求。"}],"pointGroups":[{"title":"批处理系统","indices":[0,1,2]},{"title":"功能、分类与应用","indices":[3,4]}],"pointPresentation":{"3":{"title":"批处理、分时、实时怎样选","navigationLabel":"批处理、分时、实时怎样选"},"4":{"title":"用任务要求检验分类","navigationLabel":"用任务要求检验分类"}}},{"q":6,"chapter":2,"section":"2.1","type":"单选","topic":"易用性","title":"提高易用性不靠增加系统复杂度","trigger":"题目要求找出操作系统为提高易用性通常不会采用的措施。","conclusion":"图形界面、帮助系统和多语言支持有利于易用性；无目的地增加复杂度会提高学习与操作成本。","points":["易用性强调容易学习、理解、操作和纠错。","功能丰富不等于界面复杂，良好设计会隐藏不必要的内部细节。","帮助、搜索、提示和一致的交互规则能降低认知负担。"],"boundary":"系统内部实现可能复杂，但不应把复杂度直接暴露给普通用户。","id":"y2025q6","sources":[{"year":2025,"q":6,"type":"单选"}],"keys":["2025-6"],"related":[{"id":"y2026q26","label":"任务栏承担启动、切换、状态与搜索","reason":"任务栏搜索与统一启动入口能减少寻找功能的步骤，是易用性的具体实现。"},{"id":"y2025q32","label":"“应用”保存设置但通常不关闭对话框","reason":"应用、确定、取消具有一致的操作反馈，有助于理解和纠错。"}]},{"q":2,"chapter":2,"section":"2.2","type":"单选","topic":"窗口操作","title":"活动窗口、标题栏与窗口贴靠规则","trigger":"两道题从活动窗口和拖动标题栏考查Windows窗口状态与操作。","conclusion":"活动窗口是当前操作的顶层窗口，键盘输入送到它或其内部获得焦点的控件；置顶规定覆盖顺序，最小化、最大化和还原规定显示状态。","points":["单击可操作窗口通常将其激活；普通窗口被激活后通常移到其他普通窗口前方。","非活动的置顶窗口仍可能覆盖活动窗口，因此不能只看谁在前面判断键盘输入的去向。","最小化隐藏窗口的主要内容，程序通常仍在运行；最小化不等于结束进程。","支持最大化的窗口通常可双击标题栏，在最大化与还原之间切换。","启用贴靠时，拖到顶部通常最大化，拖到左右边缘可触发贴靠；拖到底部不是标准最小化手势。","桌面承载图标、背景和打开的窗口；开始菜单提供应用与设置入口。普通应用窗口的标题栏用于识别与拖动，工作区显示内容，边框/角用于调整允许缩放的窗口。菜单中灰色命令通常暂不可用，省略号常表示还需输入条件，右箭头表示子菜单；菜单外观不能替代对实际对象的确认。","最小化暂时收起窗口，程序通常仍运行；最大化让窗口占据可用工作区；还原回到非最大化状态。关闭则结束这个窗口，未保存内容可能先触发保存提示；多窗口或后台应用不保证随一个窗口关闭而完全退出。先保存，再判断要暂时隐藏还是结束工作。","对允许调整的普通窗口，拖标题栏移动，拖边框或角调整大小。启用Windows 10贴靠时，拖到顶端可最大化，拖到左右边可贴靠；双击可最大化的标题栏可在最大化与还原间切换。拖到屏幕底端不是通用最小化方法，固定尺寸窗口和被关闭的贴靠选项应另行判断。","Alt+Tab在已打开窗口之间切换；Win+Tab打开任务视图，也可使用任务栏预览选择窗口。切换只改变当前操作对象，不会自动保存或重开文件。Alt+F4通常请求关闭当前窗口，不能把它当成最小化。"],"boundary":"可见、活动、置顶和运行是不同状态；标题栏和贴靠操作还取决于窗口能力、Windows版本及设置。","id":"y2020q2","sources":[{"year":2020,"q":2,"type":"单选"},{"year":2025,"q":8,"type":"单选"}],"keys":["2020-2","2025-8"],"comparison":{"headers":["状态","主要含义","不能直接推出"],"rows":[["活动","当前操作的顶层窗口，其内部焦点控件可接收输入","一定覆盖所有置顶窗口"],["置顶","覆盖其他非置顶窗口","一定接收键盘输入"],["最小化","窗口主要内容暂时不在桌面展开","程序已经退出"],["最大化／还原","扩大窗口／回到此前大小和位置","增加／减少正在运行的程序数"]]},"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"最小化改变窗口显示，进程通常继续运行，可用程序与进程区别排除误判。"},{"id":"y2022q34","label":"模式对话框阻塞父窗口，无模式对话框允许切回","reason":"窗口可见不代表可操作；模式对话框还会限制对父窗口的输入。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"Alt＋Print Screen截取活动窗口，必须先判断键盘焦点与置顶显示的区别。"}],"pointGroups":[{"title":"先识别桌面、窗口和控件","indices":[5]},{"title":"活动、焦点与置顶的区别","indices":[0,1]},{"title":"最小化、最大化、还原与关闭","indices":[2,6]},{"title":"移动、调整大小与贴靠","indices":[3,4,7]},{"title":"切换窗口","indices":[8]}],"pointPresentation":{"5":{"title":"先识别桌面、窗口和控件","navigationLabel":"先识别桌面、窗口和控件"},"6":{"title":"最小化、最大化、还原与关闭","navigationLabel":"最小化、最大化、还原与关闭"},"7":{"title":"移动、调整大小与贴靠","navigationLabel":"移动、调整大小与贴靠"},"8":{"title":"切换窗口不重新打开文件","navigationLabel":"切换窗口不重新打开文件"}}},{"q":34,"target":null,"chapter":2,"section":"2.2","topic":"对话框","title":"模式对话框阻塞父窗口，无模式对话框允许切回","conclusion":"模式对话框要求先完成或取消当前对话，再回到所属窗口；无模式对话框打开时仍能操作父窗口。","points":["另存为等要求确定目标的对话框通常是模式窗口。","查找等工具可作为无模式窗口，方便边查边编辑；具体行为以应用实现为准。","“应用”通常保存设置不关闭窗口，“确定”保存并关闭，“取消”放弃尚未应用的修改。","同一组单选按钮通常只能选一个；复选框可分别勾选多个；下拉列表从候选值中选择；文本框接收输入；选项卡切换同一对话框的不同设置页。先改选项，再用确定/应用提交，取消尚未提交的草稿；已应用的设置不会因为后来取消而自动撤回。","课堂的固定大小属性框一般不能像普通窗口那样最大化、最小化；但“所有对话框都不能调整大小”过于绝对。Windows的资源管理器式打开/另存为对话框可以调整大小。模式/无模式判断的是是否阻止操作其所属窗口，与有没有缩放边框是两回事。"],"boundary":"模式性描述窗口交互范围，不是对话框是否能移动，也不意味着整个操作系统都无法使用。","type":"判断","trigger":"从对话框的判断与应用整理。","id":"y2022q34","sources":[{"year":2022,"q":34,"type":"判断"}],"keys":["2022-34"],"related":[{"id":"y2025q32","label":"“应用”保存设置但通常不关闭对话框","reason":"对话框是否阻塞父窗口与按钮是否保存、关闭是两条独立规则。"},{"id":"y2020q2","label":"活动窗口、标题栏与窗口贴靠规则","reason":"父窗口暂不能操作不等于整个系统失去活动窗口，可继续区分焦点和显示状态。"}],"pointGroups":[{"title":"对话框","indices":[0,1,2]},{"title":"识别对象并完成操作","indices":[3,4]}],"pointPresentation":{"3":{"title":"从控件判断能选几个值","navigationLabel":"从控件判断能选几个值"},"4":{"title":"对话框不一律禁止缩放","navigationLabel":"对话框不一律禁止缩放"}}},{"q":32,"chapter":2,"section":"2.2","type":"判断","topic":"关机","title":"长按电源键是强制断电手段","trigger":"题目判断长按电源键能否作为正常关机方式。","conclusion":"长按电源键通常会强制关闭设备，应只在系统完全无响应且其他方法无效时使用。","points":["正常关机会让系统结束进程、写回缓存并关闭文件系统。","强制断电可能造成未保存数据丢失或文件系统损坏。","短按电源键的行为可在电源选项中配置。","正常关机可从开始→电源→关机请求系统结束会话并关机；重启随后重新启动系统。注销（退出登录）结束当前用户会话，电脑仍可供其他账户登录；锁定只阻止未认证者操作当前会话，不等于注销或关闭所有程序。Win+L用于锁定，开始菜单账户入口可退出登录。","睡眠使电脑进入低功耗状态，恢复后通常继续原工作；休眠将运行状态保存到磁盘后进入更低功耗状态。休眠是否可用取决于硬件与设置；可在电源选项中核对。两者都不能替代主动保存文档，也不能用“睡眠必然清空剪贴板”判断。","在控制面板→电源选项→选择电源按钮的功能中核对短按电源键、合盖等动作；其结果可能是睡眠等配置行为。长按强制断电绕过正常关闭流程，只能作为失去响应时的应急手段，不能据此保证文档或系统状态已保存。"],"boundary":"“可以把机器关掉”不等于“属于规范关机”。","id":"y2026q32","sources":[{"year":2026,"q":32,"type":"判断"}],"keys":["2026-32"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"应用失去响应时可先定位并结束相关进程，理解为何不应直接强制整机断电。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"未保存内容常在易失性RAM中，强制断电会失去它并中断写回。"},{"id":"y2025q33","label":"睡眠与剪贴板状态","reason":"按操作对象区分机制，再核对结果和限制。"}],"pointGroups":[{"title":"关机","indices":[0,1,2]},{"title":"识别对象并完成操作","indices":[3,4,5]}],"pointPresentation":{"3":{"title":"关机、重启与注销的对象","navigationLabel":"关机、重启与注销的对象"},"4":{"title":"睡眠与休眠怎样恢复工作","navigationLabel":"睡眠与休眠怎样恢复工作"},"5":{"title":"短按电源键为什么不固定等于关机","navigationLabel":"短按电源键为什么不固定等于关机"}},"comparison":{"headers":["操作","主要结果","不能推出"],"rows":[["锁定","会话保留，重新认证后继续","已经保存文档或注销"],["注销","结束当前用户会话","整台电脑断电"],["睡眠 / 休眠","低功耗，恢复原工作状态","等同正常关机或文件备份"],["关机 / 重启","正常结束会话并关机 / 再启动","等同长按强制断电"]]}},{"id":"syllabus-windows-paths","chapter":2,"section":"2.3","origin":"syllabus","type":"知识补充","topic":"文件层级与库","title":"文件、文件夹与路径：先找到操作对象","conclusion":"文件保存数据，文件夹组织文件和子文件夹；完整路径同时说明所在位置和名称，库与快速访问则提供组织和访问入口。","points":["文件是按名称保存的一组相关数据，例如笔记.txt、照片.jpg；文件夹用来组织文件和下一级文件夹。普通磁盘目录按树状层级组织，C:\\ 是卷的根目录，不等同于桌面上显示的所有系统对象。","完整路径 C:\\课程\\Windows\\笔记.txt 中，C: 是驱动器标识，反斜杠分隔各级目录，Windows 是所在文件夹，笔记.txt 是完整文件名。“上一级”从 Windows 回到课程；另一个目录也可以保存同名的笔记.txt。","绝对路径从盘符和根目录等完整起点定位，例如 C:\\课程\\笔记.txt；相对路径要结合当前目录解释，例如当前在 C:\\课程 时，Windows\\笔记.txt 才指向其子目录。只给文件名不能唯一确定整台电脑上的文件。","按 Win+E 打开文件资源管理器，也可单击任务栏图标或右击开始按钮选择文件资源管理器。左侧导航窗格选位置，右侧列表选项目；默认双击文件夹进入、双击文件交给关联程序打开。选择与打开是不同操作，设置为单击打开时鼠标行为也会变化。 导航项旁的三角用于展开或收起下级目录，单击名称用于定位项目，两者不能混为“都打开子目录”。","单击地址栏或按 Alt+D 可查看、输入完整路径；输入路径后按 Enter 进入。Alt+↑ 返回目录的上一级，Alt+← 返回刚访问过的位置：如果刚从 D:\\资料跳到 C:\\课程，这两个命令不会到同一个地方。","“库”把多个实际文件夹的内容汇集到一个视图，并不把原文件搬到同一物理位置。文档、图片、音乐、视频是常见默认库，也可新建库；在 Windows 10 的“查看→导航窗格→显示库”中可显示入口。库与同名的实际文件夹不是同一个对象。 添加已有目录时，可右击文件夹→包含到库中→选择目标库，或打开目标库的属性，在库位置列表中添加；还应确认可访问性和保存位置。","路径过长时应分别检查单个名称和整条路径。常见文件系统的单个名称上限为 255 个字符；传统 Win32 路径另有 MAX_PATH 限制，Windows 10 的长路径支持还取决于应用和配置。不能把“文件名 255”当成“任何完整路径都允许或只允许 255”。","向库的根视图保存文件时，会使用该库设定的默认保存位置；要保存到某一个指定目录，应明确进入那个位置，不能以为数据会同时存到库收录的每个文件夹。","删除库这个容器不会删除其收录目录的原数据；从库的位置列表移除某文件夹，只停止汇集该位置。但进入库后选中实际文件执行删除，操作作用于原文件，不是一份可随意删掉的库内副本。 要建立新的聚合视图，可在“库”下新建库并加入文件夹；默认库入口损坏时，可右击“库”选择“还原默认库”，这不会把已删除的原文件恢复出来。"],"boundary":"本节以普通 Windows 10 资源管理器和本地目录为主；此电脑、库、回收站等 Shell 对象不能全部当成普通磁盘文件夹。","sources":[],"keys":[],"searchAliases":["绝对路径","相对路径","根目录","父目录","上一级","Alt+D","Win+E","库","255","MAX_PATH"],"related":[{"id":"merged-4","label":"名称与扩展名","reason":"定位后再检查完整名称是否合法。"},{"id":"y2026q35","label":"快速访问","reason":"区分真实位置、库的聚合视图和固定入口。"}],"pointGroups":[{"title":"认识对象、路径与长度限制","indices":[0,1,2,6]},{"title":"打开和导航","indices":[3,4]},{"title":"库的视图、保存位置与移除边界","indices":[5,7,8]}],"trigger":"按 2026 年考试要求的文件与文件夹管理范围补充；具体软件事实见下列 Microsoft 资料。课堂覆盖已作内部核验，未进行原生 Windows 10 实测。"},{"q":34,"chapter":2,"section":"2.3","type":"填空","topic":"文件属性","title":"文件名、扩展名、关联、只读与权限要分层判断","trigger":"真题综合考查合法文件名、扩展名、默认打开程序，以及文件与文件夹只读属性的边界。 2023 年第 33 题的扫描题面与配套未署名参考答案存在冲突，本轮保留“仅改扩展名不转换内部格式”的机制解释，不把参考答案当官方裁决。","conclusion":"文件名、扩展名、默认打开程序、只读属性和访问权限分别约束名称、类型识别、打开方式及操作能力；不能把其中一项当成其他各项的替代。","points":["常规Windows文件名不能包含这九个字符：\\ / : * ? \" \u003c > |；连字符和数字可以使用，名称也不应以空格或句点结尾。路径C:\\资料\\笔记.txt中的冒号和反斜杠承担盘符、目录分隔功能，不是文件名“笔记.txt”的一部分。","CON、PRN、AUX、NUL、COM1至COM9、LPT1至LPT9等是保留设备名，NUL.txt等在保留名后加扩展名的形式也不能作为普通文件名。","扩展名通常参与类型识别和程序关联。Windows 10可在资源管理器“查看”选项卡勾选“文件扩展名”后再判断：显示或隐藏只改显示，更改默认应用只改打开关联，把照片.jpg改名为照片.png不会转换内部图像格式。","my.txt与无扩展名的my是不同完整文件名，可在同一文件夹共存；隐藏扩展名可能让它们看起来同名，但不改变实际名称。","只读文件通常仍可读取；普通写入或覆盖保存会受限制，但只读不等于禁止删除：资源管理器或其他工具可能先处理属性再删除，结果仍受权限、占用及具体程序影响。直接删除接口可能因只读拒绝操作；需要编辑时可按应用提示处理属性或另存为。文件夹只读标记不等于禁止创建子项，不要把属性框中的只读方块当成文件夹已被加锁。","常见属性还有隐藏、存档等；隐藏不提供保密或访问保护。能否删除还要检查权限及文件打开方式是否允许共享删除。","同一普通文件夹内，文件与子文件夹也不能使用相同的完整名称；默认名称比较不区分大小写，所以不能只把 Report.txt 改成 report.txt 就当成另一个文件。不同目录可同名，扩展名可以为空，也不是固定只能三位。","查看属性：先选中项目→Alt+Enter 或右击→属性。文件常规页可核对类型、位置、大小以及只读、隐藏等项目；常见文件还可在“打开方式→更改”选择默认应用，临时用另一应用则右击→打开方式。改变关联不会转换文件内部内容。","隐藏与显示要分两步理解：在属性中勾选“隐藏”改变该项目属性；在资源管理器“查看→隐藏的项目”决定是否显示隐藏项。它们不相互取消，隐藏项仍可通过允许的路径访问；受保护的系统文件还有单独设置，不应为找普通文件随意改变保护项。","存档是供备份等程序参考的标志，不等于已经备份，更不是 ZIP 文件；允许索引内容影响搜索收录，不等于权限或加密。“系统”也是 Windows 文件属性之一，但不是普通属性页中任意文件都可勾选的常规项目。","在支持这些功能的磁盘上，选中项目→右击→属性→常规→高级，可分别设置存档/内容索引、压缩/加密。压缩文件夹时要看清应用范围：仅改变该文件夹的默认状态，还是同时处理已有文件和子文件夹；只看父目录标记不能证明全部内容都已处理。","“加密内容以便保护数据”使用 NTFS 的 EFS，Windows 10 Home 版不提供此功能。同一文件不能同时处于 NTFS 压缩和 EFS 加密状态；这不等于 ZIP 文件不能使用其他加密方式，也不等于 Home 版不支持任何设备加密。","EFS 根据用户证书和相应私钥提供透明访问，不是给每个文件设置一个独立的打开密码，也不是知道管理员密码就一定能解密。启用后应备份并妥善保管 EFS 证书和私钥；只复制加密文件不能代替密钥备份。加密文件夹的名称仍可见，已有内容是否一并处理要核对应用范围。","Windows 10 可以选择文件或文件夹，经右击“授予访问权限→特定用户”或“共享”选项卡设置网络访问。先确认对象，再指定用户及读取/写入范围，最后用有权访问的账户核对；访问还受网络发现、连接和实际权限条件影响。文件夹共享可能涉及其内部文件，不应默认授权所有人。","常规属性中的只读/隐藏、高级属性中的压缩/加密、共享设置以及安全权限是不同层次。文件可以有共享命令，但不代表它一定具有和文件夹相同的“共享”属性页；也不能由文件夹有共享页推出“只有文件夹能够共享”。"],"boundary":"没有九个禁用字符不等于名称一定合法；基础题可按规范扩展名判断类型，实际格式须结合内容。只读、隐藏都不能替代NTFS等访问权限，也不能提供可靠防误删保证。","id":"merged-4","sources":[{"year":2020,"q":34,"type":"填空"},{"year":2023,"q":24,"type":"多选"},{"year":2023,"q":33,"type":"判断"},{"year":2023,"q":34,"type":"判断"},{"year":2026,"q":24,"type":"多选"},{"year":2022,"q":9,"type":"单选"},{"year":2021,"q":24,"type":"多选","page":4}],"keys":["2020-34","2023-24","2023-33","2023-34","2026-24","2022-9","2021-24"],"related":[{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"批量重命名不转换文件格式，移动或删除也要检查权限和占用方式。"},{"id":"y2022q75","label":"Windows 10可用“发送到→压缩(zipped)文件夹”","reason":"把扩展名改成.zip不能产生压缩包，是名称与实际格式分离的直接例子。"},{"id":"y2026q9","label":"移动存储策略可分别限制读写权限","reason":"只读属性与策略中的拒绝写入不是同一层控制，读取和写入限制还需分别判断。"}],"pointGroups":[{"title":"完整文件名是否合法","indices":[0,1,3,6]},{"title":"扩展名、关联与真实格式","indices":[2,7]},{"title":"属性与访问权限能限制什么","indices":[4,5,8,9]},{"title":"高级压缩与加密的前提","indices":[10,11,12]},{"title":"网络共享与权限的层次","indices":[13,14]}],"pointPresentation":{"0":{"title":"文件名字符与路径","navigationLabel":"文件名与类型"},"1":{"title":"保留设备名"},"2":{"title":"扩展名、关联与实际格式"},"3":{"title":"完整名称与显示名称"},"4":{"title":"只读与写入、删除权限","navigationLabel":"常规属性与权限"},"5":{"title":"隐藏、存档与访问保护"},"6":{"title":"同目录重名与大小写"},"7":{"title":"查看属性与打开方式"},"8":{"title":"隐藏属性与显示开关"},"9":{"title":"存档、索引与系统属性"},"10":{"title":"高级属性入口与应用范围","navigationLabel":"NTFS压缩入口"},"11":{"title":"EFS适用版本与压缩互斥","navigationLabel":"EFS加密"},"12":{"title":"EFS证书、私钥与备份","navigationLabel":"EFS证书与备份"},"13":{"title":"网络共享的设置步骤","navigationLabel":"共享"},"14":{"title":"属性、共享与安全权限的区别"}}},{"id":"syllabus-windows-selection","chapter":2,"section":"2.3","origin":"syllabus","type":"知识补充","topic":"选择与基本操作","title":"选择、新建与重命名：每一步先确认对象","conclusion":"先确认当前文件夹和选中范围，再执行命令；Ctrl 用于增减单项，Shift 用于连续范围，组合选择不会复制或移动文件。","points":["默认单击选中一项；要选连续项目，先选首项，再按住 Shift 单击末项，选中的是当前排列顺序中两端及中间的项目。先排序再选择，避免把“连续”误解为文件名相近。","按住 Ctrl 逐个单击可增选不连续项目；Ctrl 单击已选项可取消该项。先用 Shift 选一段，再用 Ctrl 增减个别项即可组成混合范围。按 Ctrl+A 或“主页→全部选择”可选中当前列表全部项目，“反向选择”交换已选与未选项目。","触屏或不方便按键时，可在“查看”选项卡打开“项目复选框”辅助多选。长按通常用于打开快捷菜单，不等于按住 Ctrl 选多个文件；多选后执行删除、复制等命令会作用于整个选区。","新建文件夹：先进入目标父文件夹，再按 Ctrl+Shift+N，输入名称并按 Enter；也可用“主页→新建文件夹”或列表空白处右击→新建→文件夹。新目录出现在当前父目录中；没有写入权限或名称冲突时要按提示处理。","新建文件：可在空白处右击→新建→文本文档，或在记事本、Word 等应用中“另存为”到目标目录。右键“新建”能列出哪些类型取决于已安装软件和注册项；空文件夹不是空文档，改扩展名也不能代替另存为。","单个重命名：选中一项，按 F2、使用“主页→重命名”或右键→重命名，输入新名称后按 Enter，Esc 取消。重命名改变名称，不复制文件、不改变内容；显示扩展名时应确认只改主文件名还是连扩展名一起改。 默认双击打开模式下，已选中后间隔片刻再次单击名称也可进入改名；它不是快速双击。","批量重命名要先核对选区，按 F2 输入共同主名称，再查看系统产生的带序号名称；不同扩展名及已有同名项目可能影响结果，不硬记编号总从 1 开始。改名前先确认文件类型和排序，需要精确逐个命名时应分别处理。"],"boundary":"本卡片的组合键按钮是触屏辅助。网页仅练习所列项目的选择、新建文件夹和单项改名，不代替真实资源管理器，也不模拟系统权限和所有命名例外。","sources":[],"keys":[],"searchAliases":["连续选择","不连续选择","Ctrl+A","Ctrl+Shift+N","F2","反向选择","项目复选框","新建文本文档","重命名"],"related":[{"id":"y2020q24","label":"复制、移动与拖放","reason":"选择是批量操作的前提，拖放修饰键的用途与选择不同。"},{"id":"merged-4","label":"文件名规则","reason":"重名、保留名称和扩展名需先核对。"}],"pointGroups":[{"title":"选择和取消选择","indices":[0,1,2]},{"title":"新建到正确位置","indices":[3,4]},{"title":"单项与批量命名","indices":[5,6]}],"trigger":"按 2026 年考试要求的文件与文件夹管理范围补充；具体软件事实见下列 Microsoft 资料。课堂覆盖已作内部核验，未进行原生 Windows 10 实测。","pointPresentation":{"3":{"title":"新建文件夹","navigationLabel":"新建文件夹","blocks":[{"label":"主要步骤","steps":["新建文件夹：先进入","再按","输入名称"]},{"label":"其他入口","from":"也可用"},{"label":"创建结果","from":"新目录"},{"label":"权限与重名","from":"没有写入权限"}]},"4":{"title":"新建文件","navigationLabel":"新建文件","blocks":[{"label":"操作入口"},{"label":"菜单出现哪些类型","from":"右键“新建”"},{"label":"不要混淆","from":"空文件夹"}]},"5":{"title":"单个重命名","navigationLabel":"单个重命名","blocks":[{"label":"进入改名并确认","steps":["单个重命名：选中","按 F2","输入新名称"]},{"label":"改名的结果","from":"重命名改变"},{"label":"检查扩展名","from":"显示扩展名"},{"label":"另一种入口","from":" 默认双击"}]},"6":{"title":"批量重命名","navigationLabel":"批量重命名","blocks":[{"label":"核对选区与结果","steps":["批量重命名要先核对选区","按 F2","再查看"]},{"label":"编号的限制","from":"不同扩展名"},{"label":"需要精确名称时","from":"改名前"}]}},"fieldPresentation":{"boundary":{"blocks":[{"role":"demo"}]},"trigger":{"blocks":[{},{"from":"课堂覆盖","role":"demo"}]}}},{"q":24,"chapter":2,"section":"2.3","type":"多选","topic":"文件操作","title":"复制、移动、拖放与批量重命名","trigger":"真题综合考查同盘/跨盘拖放默认规则、修饰键、剪贴板和多文件重命名。","conclusion":"资源管理器中，普通文件在同一卷的不同文件夹间左键拖动通常移动，跨卷通常复制；Ctrl、Shift、Alt及右键拖放菜单可明确请求动作。","points":["这里的“同盘／跨盘”主要按逻辑卷区分；一块物理硬盘上的C盘与D盘也属于跨卷。","Ctrl拖动通常复制，Shift拖动通常移动，Ctrl＋Shift或Alt拖动通常创建快捷方式；右键拖动可在松手后从菜单选择。","复制在目标建立副本并保留源文件；移动成功后文件离开原文件夹；快捷方式只建立指向目标的入口。","资源管理器剪切文件通常先标记待移动，粘贴成功后才完成移动；图标变淡不表示文件已经删除。","多文件可批量重命名：先用Ctrl选择不连续项目，或用Shift选择连续范围，再按F2输入共同名称；系统通常追加序号区分名称。批量改名不会把文件内容转换成另一格式，应先显示扩展名并核对选中范围。","操作失败时先读提示：同名冲突需要选择替换、跳过或另存；“拒绝访问”应检查源项与目标文件夹权限；“正在使用”应检查占用程序及共享删除方式。并非所有打开的文件都绝对不能移动或删除；也不能因为目标未出现就断言源文件已经丢失。","用剪贴板复制：选中源项目→Ctrl+C（或主页/右键菜单“复制”）→打开目标文件夹→Ctrl+V“粘贴”→核对目标副本和源文件。要移动则把 Ctrl+C 换为 Ctrl+X“剪切”，粘贴成功后再核对原位置；复制/剪切后没有粘贴，还未完成这条操作链。 也可使用“主页→复制到/移动到→选择位置”，直接指定目标后核对结果。","例如把 C:\\课程\\笔记.txt 送到 D:\\复习：Ctrl+C、切到 D:\\复习、Ctrl+V 后两处各有一份；改用 Ctrl+X 再成功粘贴，文件转到 D:\\复习。两卷在同一块物理硬盘上也不改变这个结果。","普通文档中的文本剪切往往立即从编辑区移除，而资源管理器剪切文件先标记待移动；文本能否重复粘贴还取决于应用。剪贴板传递文件时可以保存路径和数据对象，不能理解为文件已全部搬进内存，也不能通用地断言“所有剪切只可粘贴一次”。"],"boundary":"默认拖放规则以可访问、可写的普通文件夹为前提；应用、压缩包和特殊系统对象可定义其他行为，应核对松手前的动作提示。","id":"y2020q24","sources":[{"year":2020,"q":24,"type":"多选"},{"year":2023,"q":43,"type":"填空"},{"year":2025,"q":27,"type":"多选"}],"keys":["2020-24","2023-43","2025-27"],"comparison":{"headers":["拖放条件","通常动作","源文件"],"rows":[["同卷普通拖动","移动","成功后离开原文件夹"],["跨卷普通拖动","复制","保留"],["Ctrl＋拖动","复制","保留"],["Shift＋拖动","移动","成功后离开原文件夹"],["Ctrl＋Shift＋拖动","创建快捷方式","保留"],["Alt＋拖动","创建快捷方式","保留"],["右键拖动后松手","从菜单选择动作","随所选动作变化"]]},"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"移动、删除和重命名还受完整文件名、属性及访问权限约束。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"资源管理器剪切先标记待移动，成功粘贴才完成移动，与文本剪切的时机不同。"},{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"创建导航入口不复制或移动源文件，可与拖放创建快捷方式一起区分。"}],"pointGroups":[{"title":"复制和移动先看源与目标","indices":[2,6,7]},{"title":"剪切文件何时完成移动","indices":[3,8]},{"title":"按逻辑卷和拖放提示判断动作","indices":[0,1]},{"title":"批量命名与操作权限","indices":[4,5]}]},{"id":"syllabus-windows-search","chapter":2,"section":"2.3","origin":"syllabus","type":"知识补充","topic":"搜索与通配符","title":"文件搜索：先定范围，再限制名称与属性","conclusion":"资源管理器搜索先取决于当前位置和搜索范围，再判断名称、类型等条件；“没搜到”不等于文件不存在。","points":["先在资源管理器进入可能的文件夹，再在右上角搜索框输入查询并等待结果。找不到时检查搜索范围是当前文件夹还是含子文件夹，再扩大到相应磁盘或此电脑。任务栏搜索是另一个入口，不能把其结果当成某个文件夹的完整清单。","只记得名称的一部分，可先输入关键词；结果过多时再结合类型、修改日期、大小等条件。使用“详细信息”视图核对名称、类型、路径或所在位置，必要时打开文件所在位置；只凭同名或图标不能确定就是要找的文件。","按文件名模式解题时，* 表示零个或多个字符，? 表示一个任意字符。例如 笔记*.txt 可匹配笔记.txt和笔记01.txt；笔记?.txt可匹配笔记1.txt，但不匹配笔记.txt或笔记12.txt。点号分隔主文件名和扩展名，*.docx 不会把 .doc 文件转换为 .docx。","组合条件应逐项判断：模式 *复习*.txt 要求主文件名包含“复习”且扩展名为 txt；模式 ab?.* 要求主文件名为三个字符且前两位为 ab，扩展名不限。不要把“* 可以是零个字符”漏掉，也不要把问号数当成整个路径长度。","模式练习与实际搜索语法有区别：Windows 搜索还解释属性、词语和索引。需要明确按文件名匹配时，可使用规范属性查询 System.FileName:~=\"笔记*.txt\"；不要把普通关键词、全文搜索和文件名通配符结果视为永远相同。","索引用于加快检索，收录范围、更新延迟和文件类型的内容提取支持会影响结果；无权限的位置或无法提取的正文不能保证搜到。排查时依次核对位置、范围、条件和扩展名，再直接查看目标目录；先别把未命中判断成已删除。"],"boundary":"下方只演示有限样本的“文件名模式 + 范围”匹配，采用本节明确列出的 * / ? 规则；不模拟 Windows 的完整索引、AQS 解析、短文件名兼容匹配或文件正文检索。","sources":[],"keys":[],"searchAliases":["搜索范围","通配符","星号","问号","索引","System.FileName","文件搜索"],"related":[{"id":"syllabus-windows-paths","label":"路径与当前位置","reason":"搜索前先确定目录范围。"},{"id":"merged-4","label":"扩展名和隐藏","reason":"显示的名称和实际完整名称可能不同。"},{"id":"y2026q26","label":"任务栏和开始菜单搜索","reason":"2024 年题面使用 Windows 7；只复用搜索概念，不能照搬旧入口。"}],"pointGroups":[{"title":"范围与结果核对","indices":[0,1]},{"title":"通配符的完整例子","indices":[2,3]},{"title":"真实搜索的限制","indices":[4,5]}],"trigger":"按 2026 年考试要求的文件与文件夹管理范围补充；具体软件事实见下列 Microsoft 资料。课堂覆盖已作内部核验，未进行原生 Windows 10 实测。","fieldPresentation":{"boundary":{"blocks":[{"role":"demo"}]}}},{"q":75,"target":null,"chapter":2,"section":"2.3","topic":"压缩文件夹","title":"Windows 10可用“发送到→压缩(zipped)文件夹”","conclusion":"选择文件夹，右击后选择“发送到→压缩(zipped)文件夹”，系统创建一个ZIP副本，原文件夹仍保留。","points":["ZIP把所选文件内容和目录结构装入一个压缩文件；创建成功后原文件夹与ZIP副本同时存在。是否明显变小取决于原数据的可压缩性，不能把“压缩成功”理解成每个文件都必定大幅缩小。","JPEG、MP4等已压缩内容再次ZIP通常节省不多。","“添加到压缩文件”常由第三方压缩软件添加，不能假定每台Windows都有此菜单。","解压全部内容时，右击ZIP选择“全部提取”，指定目标文件夹后再核对文件；只取一项也可打开ZIP后将该项拖出。ZIP中的副本、解压得到的文件与原文件是不同位置的内容，改动其中一份不会自动同步另外两份。","完整打包步骤：在源目录选中要打包的文件或文件夹→右击→发送到→压缩(zipped)文件夹→确认 ZIP 名称→打开检查内容。选择外层文件夹会保留这层目录；只选择其内部文件则从这些项目开始打包，交作业时要核对题目要求的目录结构。","ZIP 压缩是无损打包：正常解压得到的内容与打包时相同，但仍需核对文件是否完整，不能以压缩图标代替检查。原文件后来新增或修改，不会自动更新已创建的 ZIP；要把更新后的项目重新加入或重新打包。","“属性→常规→高级→压缩内容以便节省磁盘空间”是 NTFS 文件系统压缩，文件仍在原路径、按原名称使用，不会另生成 .zip。它依赖文件系统支持；ZIP 是可复制、传递的单独文件，两者不能因都叫“压缩”就混用入口。"],"boundary":"把扩展名改为.zip只改名字，不生成合法压缩包，也不会压缩内容。","type":"综合","trigger":"从压缩文件夹的判断与应用整理。","id":"y2022q75","sources":[{"year":2022,"q":75,"type":"综合"}],"keys":["2022-75"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"扩展名只参与类型识别，生成ZIP必须实际压缩，不能只改文件名。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"JPEG、MP3等已有压缩的内容再打包通常缩小有限，要先理解有损与无损压缩。"}],"pointGroups":[{"title":"ZIP包含什么、为什么未必明显变小","indices":[0,1]},{"title":"Windows入口与解压结果","indices":[2,3]},{"title":"打包、核对与更新","indices":[4,5]},{"title":"与NTFS属性压缩区分","indices":[6]}],"pointPresentation":{"6":{"title":"NTFS压缩与ZIP的区别","navigationLabel":"NTFS压缩与ZIP的区别"}}},{"q":25,"chapter":2,"section":"2.3","type":"多选","topic":"桌面图标","title":"“此电脑”图标可通过个性化设置恢复","trigger":"题目要求识别把“此电脑”重新显示到桌面的有效入口。 已核查原卷题面及选项；“此电脑”特定对象的拖到桌面、发送到菜单行为尚未作原生 Win10 核验，配套答案未证实为官方。这里提供已由官方资料支持的系统图标恢复路径。","conclusion":"可在设置或个性化的“桌面图标设置”中勾选“计算机”，也可通过系统提供的相关入口进入该设置。","points":["“此电脑”是系统桌面图标，不等同于普通快捷方式。","Windows 10常用路径：桌面空白处右击→个性化→主题→桌面图标设置，勾选“计算机”后确定。部分较早版本的入口位置略有不同，但要进入的是同一个“桌面图标设置”对话框。","恢复图标只改变桌面显示，不会改变磁盘内容。若桌面所有图标都消失，应先右击桌面→查看，检查“显示桌面图标”；若只有此电脑缺失，再检查系统图标勾选状态。","普通文件或文件夹可右击→发送到→桌面快捷方式，或右键拖到桌面后选择创建快捷方式；系统“此电脑”的对象菜单与普通项目不同。恢复系统图标优先使用已明确的桌面图标设置路径，不能把所有普通文件菜单照搬到此电脑。","常见 Windows 快捷方式为 .lnk 文件，保存目标入口信息，并不包含目标的完整内容；同一目标可建多个快捷方式，放在不同文件夹。删除快捷方式通常不删除目标，也不会释放目标文件占用的空间。","目标改名或移动后，Windows 可能尝试重新定位，不能断言快捷方式一定失效或一定有效；目标已删除、设备未连接或无访问权限时，入口不能保证打开。右击快捷方式→属性可核对目标与位置，新建同名文件夹不能修复其目标。","桌面空白处右击→排序方式，可按名称、大小、项目类型或修改日期排列。这里的“大小”指文件数据大小，不是文件名的字符数；按类型排列也不是把文件转换类型。“查看→自动排列图标”开启时，图标按系统布局排列；要自由放到某位置，应先检查此设置，网格对齐还会约束落点。"],"boundary":"在桌面新建同名文件夹不能替代系统的“此电脑”入口。","version":"按Windows 10常见界面整理","id":"y2026q25","sources":[{"year":2026,"q":25,"type":"多选"}],"keys":["2026-25"],"related":[{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"桌面图标和快速访问都提供导航入口，恢复或固定入口不改变目标数据。"},{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"拖到桌面创建快捷方式时应核对拖放动作，避免误把入口创建当成文件移动。"}],"pointGroups":[{"title":"恢复系统图标的正确入口","indices":[0,1,2]},{"title":"系统图标与普通快捷方式","indices":[3,4,5]},{"title":"桌面排列与拖动条件","indices":[6]}]},{"q":35,"chapter":2,"section":"2.3","type":"判断","topic":"快速访问","title":"快速访问汇集常用和固定位置","trigger":"题目判断文件资源管理器中的快速访问是否方便进入常用文件夹。","conclusion":"快速访问汇集固定文件夹和常用位置，方便导航；“从快速访问取消固定”只移除固定入口，原文件夹及其内容仍在原处。","points":["可右击文件夹并选择“固定到快速访问”，让其成为方便进入的导航入口。","固定不会移动或复制原文件夹；不再需要该入口时，可执行“从快速访问取消固定”。","Windows 10 可在“查看→选项→常规→隐私”控制最近使用的文件和常用文件夹显示，清除记录只清理访问历史。快速访问里显示最近文件，不等于普通文件也能照文件夹方式固定。","在文件列表里针对实际文件或文件夹执行“删除”，仍应按普通文件删除规则判断。","库与快速访问都可提供跨位置入口：快速访问偏重常用、最近和固定位置；库把加入的文件夹内容汇集在一个视图。操作前读清命令对象：从库移除位置或删除库本身不同于在库的内容列表中删除实际文件。"],"boundary":"不要把“取消固定”“从列表移除”和“删除文件”统称为删除入口；原文件是否保留取决于执行的具体命令。","id":"y2026q35","sources":[{"year":2026,"q":35,"type":"判断"}],"keys":["2026-35"],"related":[{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"取消固定不进入回收站；只有针对实际文件执行删除才判断回收位置和方式。"},{"id":"y2026q25","label":"“此电脑”图标可通过个性化设置恢复","reason":"系统桌面图标、普通快捷方式和固定位置都是不同入口类型，不能用同名文件夹替代。"}],"pointGroups":[{"title":"固定、取消与访问记录","indices":[0,1,2]},{"title":"入口移除和删除原文件","indices":[3,4]}]},{"q":3,"chapter":2,"section":"2.3","type":"单选","topic":"回收站","title":"Delete是否进入回收站取决于位置和方式","trigger":"结合删除位置、操作方式与提示，判断是否进入回收站以及如何还原。","conclusion":"本地可回收位置的普通Delete通常将文件移入回收站；Shift＋Delete、网络位置、部分移动介质及容量或策略设置可能使文件绕过回收站。","points":["回收站不是所有存储位置的统一保险箱，是否可回收要结合位置、删除方式和实际提示判断。 例如普通 U 盘中直接按 Delete 删除，通常绕过本机回收站，不能用回收站还原；剪贴板也不是删除文件的自动备份。移动硬盘、网络/云服务的回收策略可能不同，仍以具体位置和提示为准。","回收站使用磁盘空间，普通关机或重启不会因为断电自动清空。移入回收站的文件仍占用存储空间；清空或从其中永久删除后，才释放相应文件占用的空间。","从回收站还原通常回到原文件夹；应核对原路径，避免只凭文件名判断恢复位置。","删除快捷方式与删除其目标文件是不同操作，应先确认选中的是哪个对象。","绕过或清空回收站后，不能再用该回收站的还原功能取回文件；其他备份或恢复工具能否恢复取决于具体条件。","普通删除流程：在原文件夹选中项目，按 Delete、右击→删除或用“主页→删除”；确认提示中的对象、数量和删除方式。按住 Shift 执行删除或按 Shift+Delete 会请求绕过回收站，应先确认有无备份。 删除普通文件夹会连同其内部文件和子文件夹一起处理，应核对整棵目录的内容。","还原流程：打开回收站，核对“原位置”和删除日期，选中所需项目→右击→还原；需要全部恢复可用“还原所有项目”。若原路径或同名文件发生变化，按系统提示处理；先还原再到原位置打开核对内容。 若想取回到另一目录，可从回收站选中项目后剪切并粘贴到目标，或拖到指定目录；这与“还原到原位置”应分开判断。 需要继续阅读、编辑或改名时，先取回到普通目录再操作，不把回收站当作日常工作目录。","回收站里选中项目→删除，只永久移除所选项；“清空回收站”影响其中全部项目。右击桌面回收站→属性可按驱动器调整容量、直接删除选项和确认提示；容量限制、自动清理配置等意味着它不是永久保管箱。 桌面图标可在“桌面图标设置”中隐藏或恢复；隐藏图标不等于删除系统回收功能。","Ctrl+Z 可以撤销资源管理器中仍有撤销记录且允许撤销的近期操作，也可查看“撤销”命令所写的具体动作。它不是所有操作的保险：绕过回收站、清空、应用内操作或会话变化不能保证可撤销。不要在不确认目标动作时连续按键。"],"boundary":"“永久删除”不等于已安全擦除全部数据，也不保证还能恢复；题干出现“一定”“所有”时，须检查介质、删除方式、容量和配置。","id":"y2020q3","sources":[{"year":2020,"q":3,"type":"单选"},{"year":2025,"q":35,"type":"判断"},{"year":2022,"q":45,"type":"填空"}],"keys":["2020-3","2025-35","2022-45"],"related":[{"id":"y2026q35","label":"快速访问汇集常用和固定位置","reason":"取消快速访问固定只移除入口；真正删除文件才适用回收站规则。"},{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"清空回收站能释放空间，但清理前应核对其中是否仍有需要恢复的文件。"},{"id":"y2026q33","label":"关闭系统保护会删除还原点并释放空间","reason":"回收站恢复与系统还原保护的对象不同，系统还原不能代替个人文件备份。"}],"pointGroups":[{"title":"回收位置、空间占用与还原","indices":[0,1,2]},{"title":"确认删除对象与恢复边界","indices":[3,4]},{"title":"删除、还原与设置步骤","indices":[5,6,7]},{"title":"撤销的适用前提","indices":[8]}]},{"q":23,"chapter":2,"section":"2.4","type":"多选","topic":"控制面板与账户","title":"控制面板视图与管理员账户的权限边界","trigger":"真题从控制面板任务、显示方式和用户账户类型考查Windows经典设置入口。","conclusion":"控制面板可管理账户、程序、外观和防火墙等设置；管理员账户可在确认提升后执行影响全系统或其他用户的管理操作。","points":["控制面板可按类别、大图标或小图标显示；改“查看方式”只改变项目排列，不改变权限，也不会安装或卸载功能。","标准账户可完成日常操作；需要管理员权限的安装或系统配置操作触发UAC提升。在常见默认配置下，管理员账户确认提升，标准账户则需要提供有效管理员凭据；提示方式还受策略影响。","Windows 10部分经典入口会跳转到“设置”应用。","账户显示名称可以按账户类型和权限修改；管理内置Administrator与普通管理员账户不是一回事。Windows 10日常权限判断以标准账户、管理员及UAC提升为主。","教学示例：能打开控制面板、查看当前设置，不代表能修改影响全系统的项目。带盾牌的管理按钮可能进一步要求提升；取消这次提升，只是该次管理操作没有获准，不会自动把账户类型改为标准账户。","开始搜索“控制面板”或Win+R输入control可打开传统控制面板；Win+I打开设置。要改背景/主题，进入设置→个性化；要改显示分辨率，进入设置→系统→显示。两个入口仍有并存和跳转，Windows 10小版本可能改变位置，应先认准设置对象。","控制面板“日期和时间”调整时钟、时区等；“区域→格式/其他设置”调整日期、时间、数字和货币的显示格式。把日期格式改成另一种写法不等于改变当前日期。更改系统时间可能要求管理员提升，不能由“能查看时钟”推导出“能更改时钟”。","鼠标属性可调主次按钮、双击速度、指针及滚轮；把左键与右键功能交换不等于改变文件本身。声音设置可选择事件提示音并测试，课堂系统事件声音使用WAV；不要由扩展名进一步断言所有WAV文件都一定未压缩。改动后通过应用/确定保存，再实际核对结果。","标准用户能完成一般日常任务；涉及系统级改变时，UAC可能要求管理员凭据。管理员也通常先以受限令牌运行，提权后仍不意味着自动拥有所有文件或能解密任何EFS文件。账户类型、文件所有权、NTFS权限和加密密钥是不同层次，访问失败要分别检查。"],"boundary":"管理员不表示所有程序始终以最高权限运行；控制面板也不能替代任务管理器管理每个进程。","id":"y2025q26","sources":[{"year":2023,"q":23,"type":"多选"},{"year":2023,"q":44,"type":"填空"},{"year":2025,"q":26,"type":"多选"},{"year":2021,"q":5,"type":"单选","page":2},{"year":2021,"q":34,"type":"填空","page":6}],"keys":["2023-23","2023-44","2025-26","2021-5","2021-34"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"控制面板管理系统设置，任务管理器管理运行活动，遇到进程问题应选对入口。"},{"id":"y2026q9","label":"移动存储策略可分别限制读写权限","reason":"可移动存储的读写策略需要授权管理，管理员身份仍要结合提升与版本能力。"},{"id":"merged-4","label":"文件权限与EFS不是账户类型","reason":"按操作对象区分机制，再核对结果和限制。"}],"pointGroups":[{"title":"控制面板与设置的入口、视图","indices":[5,0,2]},{"title":"账户身份、UAC与操作权限","indices":[1,3,4,8]},{"title":"日期、区域、鼠标与声音的设置","indices":[6,7]}],"pointPresentation":{"5":{"title":"按对象找到设置入口","navigationLabel":"按对象找到设置入口"},"6":{"title":"日期时间与区域格式不是一件事","navigationLabel":"日期时间与区域格式不是一件事"},"7":{"title":"鼠标与声音的设置边界","navigationLabel":"鼠标与声音的设置边界"},"8":{"title":"管理员、标准用户和文件权限","navigationLabel":"管理员、标准用户和文件权限"}}},{"q":32,"chapter":2,"section":"2.4","type":"判断","topic":"对话框按钮","title":"“应用”保存设置但通常不关闭对话框","trigger":"题目判断Windows对话框中单击“应用”后的结果。","conclusion":"“应用”通常让修改立即生效并保留对话框，“确定”通常应用修改并关闭对话框。","points":["“取消”通常关闭并放弃尚未应用的修改。","已单击“应用”的修改不一定能再由“取消”撤销。","按钮行为仍以具体程序实际设计为准。"],"boundary":"不要把“应用”和“确定”的共同点背成完全相同；关键差异是是否关闭窗口。","id":"y2025q32","sources":[{"year":2025,"q":32,"type":"判断"}],"keys":["2025-32"],"related":[{"id":"y2022q34","label":"模式对话框阻塞父窗口，无模式对话框允许切回","reason":"应用或确定描述按钮行为，模式或无模式描述父窗口能否继续操作，应分开判断。"}]},{"q":44,"chapter":2,"section":"2.4","type":"填空","topic":"任务栏与搜索","title":"任务栏承担启动、切换、状态与搜索","trigger":"真题从任务栏组成、开始菜单搜索和搜索范围考查Windows桌面入口。","conclusion":"任务栏集中提供开始菜单、应用启动与切换、搜索、任务视图和系统状态；搜索可定位应用、设置和建立索引的本地文件。","points":["搜索框可隐藏或仅显示图标，也可直接在开始菜单输入。","搜索结果受索引、权限、版本和网络配置影响。","通知区域显示网络、音量、时间等状态。","Windows 10任务栏右键菜单可打开任务管理器、设置任务栏；任务栏最右端可显示桌面。应用自身的功能设置仍要进入应用。","Windows 10搜索可涉及本地文件、应用、设置及网络结果；具体网络结果受配置和连接影响，不能说搜索只能用于本地。","桌面右键→个性化→背景，可选择纯色、图片或幻灯片放映；背景设置不属于任务栏右键菜单的直接功能。","右击应用→固定到任务栏，可保留启动入口；取消固定不卸载程序。任务栏按钮可启动或切换应用，通知区域显示网络、音量、时钟等状态；不能用按钮数量代替进程数量。开始菜单中的磁贴是常用入口，取消固定同样不等于删除程序。","Windows 10任务栏可在屏幕上、下、左、右边。右击空白处→任务栏设置可核对位置与自动隐藏；解锁后拖边框调整尺寸，底部横向任务栏调整的是高度。课堂“能改高度不能改宽度”针对横向布局，不应推广为所有位置的绝对限制。锁定主要防止拖动误改，不等于禁止自动隐藏。","Win+Tab进入任务视图，可组织多个虚拟桌面上的窗口；关闭虚拟桌面不等于卸载其中的应用。Win+Space在已安装的输入语言/键盘布局间切换；中英文、全半角等切换还取决于输入法及快捷键配置，不能把某输入法的组合键当成所有Windows输入都通用。"],"boundary":"没有搜到不等于文件不存在；桌面背景设置也不属于任务栏功能。","id":"y2026q26","sources":[{"year":2024,"q":44,"type":"填空"},{"year":2025,"q":9,"type":"单选"},{"year":2026,"q":26,"type":"多选"},{"year":2022,"q":7,"type":"单选"}],"keys":["2024-44","2025-9","2026-26","2022-7"],"related":[{"id":"y2020q2","label":"活动窗口、标题栏与窗口贴靠规则","reason":"任务栏切换应用后仍需区分窗口是否活动、最小化以及进程是否运行。"},{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"任务栏可提供任务管理器入口，进一步查看当前进程与资源占用。"},{"id":"y2026q25","label":"“此电脑”图标可通过个性化设置恢复","reason":"桌面系统图标与背景设置属于个性化范围，不能把所有桌面相关操作都归入任务栏。"}],"pointGroups":[{"title":"任务栏的启动、状态与管理入口","indices":[6,2,3]},{"title":"位置、尺寸和自动隐藏","indices":[7]},{"title":"搜索入口及结果范围","indices":[0,1,4]},{"title":"任务视图与输入法","indices":[8]},{"title":"桌面背景应在哪里设置","indices":[5]}],"pointPresentation":{"6":{"title":"固定入口、运行窗口和通知区域","navigationLabel":"固定入口、运行窗口和通知区域"},"7":{"title":"任务栏位置、尺寸和自动隐藏","navigationLabel":"任务栏位置、尺寸和自动隐藏"},"8":{"title":"任务视图与输入法先认对象","navigationLabel":"任务视图与输入法先认对象"}}},{"q":24,"chapter":2,"section":"2.4","type":"多选","topic":"任务管理与远程边界","title":"任务管理器管理当前主机的进程、性能和启动项","trigger":"真题从结束应用、查看资源、远程桌面边界与常用命令考查任务管理器。","conclusion":"任务管理器直接管理当前会话所在系统，可查看或结束进程、查看性能、管理启动项；远程桌面连接后管理的是远程主机。","points":["Ctrl＋Shift＋Esc可打开任务管理器；Windows 10简略界面可先点“详细信息”。应用无响应时应先选中对应任务再结束；这会终止运行活动，可能丢失未保存内容，但不会卸载软件。","性能页显示CPU、内存、磁盘和网络资源，进程页便于比较哪个任务占用较多。教学示例：CPU持续占用高时先看进程列表，不能仅凭电脑变慢就断言硬盘已满。","远程连接必须满足网络、系统设置、认证和授权条件。","可针对相应进程打开文件所在位置、查看属性；“启动”页可启用或禁用启动项。禁用启动项主要影响以后登录时是否自动启动，不等于立即结束已经运行的进程，也不等于删除程序文件。"],"boundary":"任务管理器不是完整卸载器，也不是绕过权限的远程监控平台。","id":"y2026q34","sources":[{"year":2024,"q":24,"type":"多选"},{"year":2024,"q":34,"type":"判断"},{"year":2025,"q":28,"type":"多选"},{"year":2026,"q":34,"type":"判断"}],"keys":["2024-24","2024-34","2025-28","2026-34"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"任务管理器列出运行实例，因此结束任务不等于删除磁盘上的程序文件。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"需要移除软件主体时应卸载，不能以结束进程替代。"},{"id":"y2026q8","label":"设备管理器查看硬件与驱动状态","reason":"进程异常与硬件驱动异常使用不同管理工具，先按问题对象选择入口。"}],"pointGroups":[{"title":"进入任务管理器并定位异常","indices":[0,1]},{"title":"远程会话与启动项的边界","indices":[2,3]}]},{"q":45,"chapter":2,"section":"2.4","type":"填空","topic":"设备管理器","title":"设备管理器查看硬件与驱动状态","trigger":"真题从工具名称和异常图标考查硬件设备管理。","conclusion":"设备管理器列出硬件类别和状态，可查看驱动、启用或禁用设备、扫描硬件改动；黄色感叹号提示需要进一步诊断。","points":["Windows 10可右击开始按钮打开“设备管理器”，展开设备类别，再右击异常设备→属性，读取“设备状态”和错误代码。黄色感叹号只提示有问题，不能直接等同于“设备损坏”。","教学示例：代码28表示设备驱动未安装，应核对设备型号、系统版本和驱动来源，再安装匹配的驱动。其他错误码要按各自说明处理，不能看到黄色标记就一律更换硬件或反复更新同一个驱动。","磁盘分区、盘符等主要由磁盘管理工具负责；设备管理器的“扫描检测硬件改动”是重新检测设备，不能替代分区、格式化或修复所有硬件故障。","先右击开始→设备管理器，展开类别并查看设备属性中的状态/错误代码，再决定启用、更新或重新安装匹配驱动。即插即用设备在已有合适驱动时可自动配置，不能说每台打印机都必须手动安装驱动。驱动使系统能使用设备，打印队列则处理待打印文档的暂停/取消，不是卸载任意应用的入口。"],"boundary":"异常图标是线索，不是最终原因；设备消失也可能来自连接或硬件问题。","id":"y2026q8","sources":[{"year":2024,"q":45,"type":"填空"},{"year":2026,"q":8,"type":"单选"}],"keys":["2024-45","2026-8"],"related":[{"id":"y2026q34","label":"任务管理器管理当前主机的进程、性能和启动项","reason":"硬件及驱动状态由设备管理器处理，CPU占用与进程结束则看任务管理器。"}],"pointGroups":[{"title":"从入口读到错误代码","indices":[0,1]},{"title":"和磁盘管理分别处理什么","indices":[2]},{"title":"入口、对象与权限边界","indices":[3]}],"pointPresentation":{"3":{"title":"驱动管理与打印任务管理分开","navigationLabel":"驱动管理与打印任务管理分开"}}},{"q":9,"chapter":2,"section":"2.4","type":"单选","topic":"组策略","title":"移动存储策略可分别限制读写权限","trigger":"题目考查本地组策略中对USB等可移动存储设备的访问控制。","conclusion":"Windows策略可以分别配置可移动磁盘的读取、写入和执行权限。","points":["拒绝写入可防止向设备复制数据，但仍可能允许读取。","拒绝读取会阻止访问设备内容，通常也使正常使用受到更大限制。","策略修改应由授权管理员进行，并考虑组织安全规范。","在具备本地组策略编辑器的Windows 10专业版、企业版、教育版等环境，可检查计算机配置→管理模板→系统→可移动存储访问的“可移动磁盘：拒绝读取权限”等项。启用拒绝读取并不等于启用拒绝写入；还要检查拒绝所有访问等其他有效策略。家庭版通常不提供该编辑器。","组策略对相应计算机/用户的访问施加限制；NTFS权限作用于文件系统对象；介质物理写保护又是另一层。某U盘在本机被拒绝读取，不能推出它在任何电脑都不可读，也不能据此宣称绝对不会感染恶意代码。"],"boundary":"策略名称和可用项会随Windows版本与版本类型变化，家庭版通常不提供完整本地组策略编辑器。","id":"y2026q9","sources":[{"year":2026,"q":9,"type":"单选"}],"keys":["2026-9"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"拒绝写入的策略与文件只读属性、目录权限分别生效，不能用隐藏属性代替访问保护。"},{"id":"y2025q26","label":"控制面板视图与管理员账户的权限边界","reason":"修改影响系统的存储策略前要确认授权和管理员提升，账户名称本身不保证最高权限。"}],"pointGroups":[{"title":"组策略","indices":[0,1,2]},{"title":"入口、对象与权限边界","indices":[3,4]}],"pointPresentation":{"3":{"title":"读、写策略与权限不是同一层","navigationLabel":"读、写策略与权限不是同一层"},"4":{"title":"判断限制作用于哪里","navigationLabel":"判断限制作用于哪里"}}},{"q":4,"chapter":2,"section":"2.5","type":"单选","topic":"剪贴板","title":"粘贴和正常睡眠通常不会自动清空剪贴板","trigger":"真题从重复粘贴与睡眠唤醒两个场景考查剪贴板内容的保留。","conclusion":"文本、图片等内容粘贴后通常仍可继续粘贴，正常睡眠与唤醒也不必然清空剪贴板；资源管理器的文件剪切移动及剪贴板历史须分别判断。","points":["复制或剪切通常更新当前剪贴板内容；Ctrl＋V粘贴当前内容，普通粘贴本身通常不会将文本或图片内容用完。","文本剪切通常立即移除选中文字；资源管理器剪切文件通常只标记待移动，粘贴成功后才完成位置变化。","复制文件时，剪贴板可记录文件位置与传输信息，不能把它当成整个文件已经完整备份到内存。","Windows 7 普通系统剪贴板按当前项理解，不带后来 Windows 10 的 Win+V 历史。Windows 10 在 2018 年 10 月更新引入该历史功能，开启后可用 Win+V 选择较早的受支持项目；当前项、Windows 历史与 Office 剪贴板是不同概念，不能拿新版历史推翻旧版题目的前提。","正常睡眠通常保留当前会话，但不能与关机或重启混为一谈；重启会清除未固定的Windows历史项目，固定项目可保留。","传统Windows截图按键中，Print Screen复制全屏，Alt＋Print Screen复制活动窗口，结果进入剪贴板；重新配置按键行为时按实际设置执行。"],"boundary":"文件剪切移动完成后，不能据“文本可重复粘贴”推断必能再次粘贴出文件副本；Windows历史有格式、大小和数量限制，不能保存任意文件。策略、程序行为和手动清除也可能影响内容。","id":"y2025q33","sources":[{"year":2023,"q":4,"type":"单选"},{"year":2025,"q":33,"type":"判断"}],"keys":["2023-4","2025-33"],"comparison":{"headers":["场景","剪切或复制后","粘贴或重启后"],"rows":[["文本剪切","所选文字通常立即离开源位置","粘贴后通常仍可继续粘贴"],["文件剪切","源文件通常仍在，只被标记待移动","粘贴成功后才完成移动，不按重复复制理解"],["文件复制","源文件保留，剪贴板提供文件传输信息","目标建立副本，仍依赖源文件可访问"],["Windows剪贴板历史","开启后可保留支持的较早项目","重启清除未固定项目，固定项目可保留"]]},"related":[{"id":"y2020q24","label":"复制、移动、拖放与批量重命名","reason":"文件剪切粘贴是位置移动，不能照搬文本可重复粘贴的结论。"},{"id":"y2026q3","label":"RAM与ROM的断电特性","reason":"普通剪贴板与RAM暂存有关，固定历史等额外功能不能一概按断电丢失处理。"},{"id":"y2025q34","label":"Windows附件各有功能边界","reason":"粘贴是否保留表格与图片还取决于目标应用，纯文本记事本不会保留Word丰富结构。"}],"pointGroups":[{"title":"复制、剪切与粘贴何时改变内容","indices":[0,1,2]},{"title":"剪贴板历史与睡眠、重启","indices":[3,4]},{"title":"截图怎样进入剪贴板","indices":[5]}]},{"q":33,"chapter":2,"section":"2.5","type":"判断","topic":"软件卸载","title":"卸载程序不保证清除所有关联文件","trigger":"题目判断从Windows卸载应用后是否一定删除所有文件和设置。","conclusion":"卸载通常移除程序主体和注册信息，但可能保留用户文档、配置、缓存、日志或共享组件。","points":["保留配置可方便以后重装恢复偏好。","用户创建的数据通常不应被卸载器擅自删除。","需要彻底清理时应先备份，再按软件官方说明检查残留。","Windows 10可在设置→应用→应用和功能选择程序→卸载，传统桌面程序也可由控制面板→程序和功能卸载。按卸载程序提示完成，再检查是否还列在已安装程序中；某些程序还提供更改/修复，不能假定每个程序都有同样按钮。","免安装程序通常解包即可运行，但“免安装”不等于破解或无需授权。已安装程序直接删除目录可能留下注册与组件信息，应使用卸载入口；结束任务只是停止当前进程。即使成功卸载，也可能保留个人文档、配置或缓存，应按实际需要另外核对。"],"boundary":"残留不一定是故障或垃圾；共享组件和用户数据不能仅凭目录名称直接删除。","id":"y2024q33","sources":[{"year":2024,"q":33,"type":"判断"}],"keys":["2024-33"],"related":[{"id":"y2022q44","label":"程序是静态代码，进程是一次运行实例","reason":"停止一次运行只结束进程；卸载涉及程序主体，两者都不等于自动删除用户数据。"},{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"程序残留与可安全清理的临时内容要先分类核对，不能只按文件夹名称批量删除。"}],"pointGroups":[{"title":"软件卸载","indices":[0,1,2]},{"title":"选择工具并核对影响","indices":[3,4]}],"pointPresentation":{"3":{"title":"通过卸载入口移除已安装程序","navigationLabel":"通过卸载入口移除已安装程序"},"4":{"title":"免安装、删除目录与结束任务","navigationLabel":"免安装、删除目录与结束任务"}}},{"q":5,"chapter":2,"section":"2.5","type":"单选","topic":"磁盘清理","title":"磁盘清理用于移除可安全删除的系统临时内容","trigger":"题目要求选择用于清理临时文件、回收站内容和系统残留的Windows工具。","conclusion":"Windows 10磁盘清理先扫描指定驱动器，再删除用户确认的文件类别以释放空间；“设置→系统→存储”中的临时文件功能也可处理相应内容。","points":["先阅读待删除类别及说明，再决定是否勾选；看到回收站、下载等项目时，须确认其中没有需要保留的文件。“下载的程序文件”是一个特定缓存类别，不能只因名称带“下载”就把它等同于个人“下载”文件夹。","卸载应用移除程序主体，清理临时内容移除工具列出的缓存或残留，两者处理的对象不同。应用仍在正常使用不妨碍清理可删除的临时项目，清理也不等于将该应用卸载。","“碎片整理和优化驱动器”处理存储布局或设备优化；机械硬盘可整理碎片，SSD可执行TRIM等优化。它与磁盘清理不是同一工具，优化驱动器不会代替勾选删除临时文件。","Windows 10操作顺序：开始菜单搜索“磁盘清理”→选择驱动器→等扫描完成→勾选类别；要查系统残留可点“清理系统文件”并重新扫描，最后点“确定”并确认“删除文件”。只扫描或勾选尚未完成删除。","教学示例：临时文件300 MB、回收站200 MB，只勾选临时文件，本次计划释放约300 MB，回收站内容仍保留。清理后核对可用空间；列表内容和可释放量取决于本次驱动器与扫描结果，并非每台机器都有相同项目。","清理选择可删除的临时等文件类别；格式化重建指定卷的文件系统，原文件将不能照原目录直接访问。格式化前须确认盘符、文件系统与备份，不能把它当作清理缓存按钮，更不能拿真实系统盘做本页练习。","快速格式化主要重建文件系统管理信息，不逐扇区扫描坏区域；常规格式化会进行更多检查、耗时通常更长。不能把旧数据“看不见”当成安全擦除证明，也不能由“快速”推出原数据必定可恢复；介质、覆盖与SSD行为都会影响恢复。Windows 10具体完整格式化的写零及介质例外需按工具与参数核对。","空间不足时先判断是临时文件多、软件不再需要，还是要重新初始化整卷：三者分别对应清理、卸载、格式化。整理碎片不扩大磁盘物理容量；SSD按介质采用适当优化，不能把“优化驱动器”概括为“所有磁盘都应频繁做传统碎片整理”。"],"boundary":"清理工具不是备份工具。清空回收站后不能再从该回收站还原；删除“以前的Windows安装”等项目会失去对应的系统版本回退文件，不能一律把扫描出的项目当成自己不再需要的文件。","id":"y2024q5","sources":[{"year":2024,"q":5,"type":"单选"}],"keys":["2024-5"],"related":[{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"清空回收站才释放被回收文件的空间，也会失去该回收站的直接还原能力。"},{"id":"y2024q33","label":"卸载程序不保证清除所有关联文件","reason":"卸载软件与清理临时文件删除的对象不同，不能把用户文档当作卸载残留清除。"},{"id":"y2026q33","label":"关闭系统保护会删除还原点并释放空间","reason":"还原点也占空间，但删除它们会降低恢复能力，应与普通临时内容分开判断。"}],"pointGroups":[{"title":"先确认删除对象","indices":[0,1]},{"title":"清理与驱动器优化的区别","indices":[2]},{"title":"扫描、选择、确认与结果核对","indices":[3,4]},{"title":"选择工具并核对影响","indices":[5,6,7]}],"workedExamples":[{"year":2024,"q":5,"questionSummary":"根据删除临时内容与清空回收站的目的选择系统工具。","reasoning":["先认操作对象：题设要求移除不再需要的文件以释放空间。","磁盘清理扫描可清理类别并按选择删除；系统还原用于恢复系统状态，磁盘检查面向文件系统错误，碎片整理面向文件在存储介质上的布局。","因此应选磁盘清理；“电脑变慢”只是现象，不能只凭改善性能这个共同结果选碎片整理。"],"pitfall":"把磁盘清理与碎片整理混淆，或误以为清理必然删除所有个人文件。","transfer":"迁移到Windows 10时，仍先确认“要删除什么”；“存储→临时文件”也是相关入口。清理前核对下载、回收站和旧系统安装等类别。","sourceURL":"https://www.aipta.com/article/10360.html","sourceStatus":"本轮已核查原卷题面、选项及配套参考答案对应页；配套答案的发布机构和官方性未确认。","historicalVersionNote":"该年公开题面沿用Windows 7/Office 2010。此处保留原题语境；站内操作入口须按Windows 10/Office 2016另行说明。"}],"pointPresentation":{"5":{"title":"格式化与清理的对象不同","navigationLabel":"格式化与清理的对象不同"},"6":{"title":"快速格式化与常规格式化","navigationLabel":"快速格式化与常规格式化"},"7":{"title":"清理、整理、优化分别解决什么","navigationLabel":"清理、整理、优化分别解决什么"}}},{"q":33,"chapter":2,"section":"2.5","type":"判断","topic":"系统还原","title":"关闭系统保护会删除还原点并释放空间","trigger":"题目判断禁用系统还原是否能释放磁盘空间。","conclusion":"关闭某驱动器的系统保护并删除已有还原点可以释放其占用空间。","points":["还原点记录系统文件、注册表、应用及系统设置在某时刻的状态，用于系统异常后的回退。还原点保存在磁盘上并占用配额，不是只在RAM中的临时内容。","系统还原不是个人文件备份。教学示例：驱动更新后出现故障，可以考虑回到较早还原点；误删一份学习文档则应查回收站或文件备份，不能指望系统还原自动把文档找回。","Windows 10可搜索“创建还原点”→系统保护→选中驱动器→配置，查看当前占用与最大使用量。按需要调整配额或清理旧还原点，应同时考虑保留哪些恢复能力；不能把释放空间理解成完全没有代价。","搜索“创建还原点”打开系统保护，选目标驱动器→配置，核对保护开关和空间上限；启用保护后可“创建”并填写说明。开关打开或增大上限不等于已经存在可用还原点，改变重要系统配置前应检查创建结果。","控制面板→恢复→打开系统还原（也可运行rstrui.exe），选择问题发生前的还原点，查看“扫描受影响的程序”，确认后完成并按提示重启。还原会回退相应系统文件、注册表、驱动和程序状态；不是只把还原点从列表中删除。","系统还原不以恢复个人文档为目的；误删笔记应先核对回收站或个人文件备份。系统映像用于更完整的系统恢复，重置此电脑涉及重新安装Windows，均不等于应用一个还原点。本节只辨别用途，不展开备份与运维教程。","个人文件备份的官方补充入口：连接外部驱动器或选网络位置→控制面板→系统和安全→文件历史记录，选择驱动器并启用，核对实际备份的文件夹与版本。恢复前先预览所需版本；需要保留现有文件时选择还原到其他位置，避免覆盖。只有此前已备份的内容和版本才可据此恢复，不能先删除文件再指望新开启的备份追溯找回。"],"boundary":"释放空间会牺牲恢复能力，操作前应确保有其他可靠备份。","id":"y2026q33","sources":[{"year":2026,"q":33,"type":"判断"}],"keys":["2026-33"],"related":[{"id":"y2024q5","label":"磁盘清理用于移除可安全删除的系统临时内容","reason":"释放磁盘空间时可比较临时内容和还原点；后者还承担系统恢复用途。"},{"id":"y2020q3","label":"Delete是否进入回收站取决于位置和方式","reason":"系统还原不替代回收站还原或文件备份，三者保护的对象和条件不同。"}],"pointGroups":[{"title":"还原点保护什么","indices":[0,1]},{"title":"怎样查看和权衡空间占用","indices":[2]},{"title":"选择工具并核对影响","indices":[3,4,5,6]}],"pointPresentation":{"3":{"title":"建立还原点，再核对可恢复状态","navigationLabel":"建立还原点，再核对可恢复状态","blocks":[{"label":"建立还原点"},{"from":"开关打开","label":"核对结果"}]},"4":{"title":"选择还原点并查看影响","navigationLabel":"选择还原点并查看影响","blocks":[{"label":"操作步骤"},{"from":"还原会回退","label":"结果与边界"}]},"5":{"title":"还原系统不等于找回个人文件","navigationLabel":"还原系统不等于找回个人文件"},"6":{"title":"个人文件另做备份","navigationLabel":"文件历史记录与还原范围","blocks":[{"label":"操作入口"},{"from":"恢复前先预览","label":"恢复前核对"},{"from":"只有此前已备份","label":"适用前提"}]}}},{"q":25,"chapter":2,"section":"2.6","type":"多选","topic":"Windows实用工具","title":"Windows附件各有功能边界","trigger":"真题从截图、记事本、计算器、画图和水印处理考查系统工具。","conclusion":"本章以Windows 10传统附件为准：记事本能调整整篇的字体、字形和字号显示，却不把逐字格式保存到TXT；计算器、画图和截图工具各处理不同任务。","points":["Windows 10传统截图工具可选择任意形状、矩形、窗口或全屏截图；截取后还要按需要保存文件，保存类型以该工具“另存为”列表为准。截图记录屏幕图像，不会自动变成可编辑的Word文字。","画图通过“文件→另存为”选择格式，会按所选格式重新保存图像；仅改扩展名不会转换图像。有损格式如JPEG可能丢失细节，即使以后另存为无损格式，也不能自动找回已经丢掉的细节。","截图工具保留截取区域中的水印；橡皮擦通常用于擦除自己添加的标注，不能把“截图”理解为自动去除原图水印。水印修改还涉及图像编辑、授权和内容真实性。","Windows 10传统记事本处理纯文本：粘贴Word表格或网页内容时，可保留能以文字表示的内容，但不保留原表格边框、单元格对象、图片及逐字富文本格式。用空格或制表符排成几列，仍不等于真正的表格。","传统记事本可以在“格式→字体”里改字体、字形和字号：字体是所选字体名称，字形指常规、粗体、斜体等，字号控制文字大小。设置用于整篇显示，即使只选中一部分文字，也不能像Word那样仅给那部分保存独立字体格式。","记事本的显示偏好与TXT文件内容分开。教学示例：把同一段A中显示成另一字体、粗体或较大字号，只是观看方式变化；在文字、编码、BOM与换行均相同的前提下，保存的文本字节不因这些显示设置而改变。换一台电脑打开时，不能要求TXT还原原来的字体外观。","计算器中打开导航菜单→日期计算，可求两个日期相差的天数，或从指定日期增加、减去年、月、日。教学示例：9月1日到9月4日的日期差为3天；若另外问“首尾两天都计入共几天”，需要结合题意作包含端点的计数。","需要保留字符/段落格式或插入图片时，可选Windows 10写字板；新文档默认常见格式为RTF，也可在另存为中选择其他支持类型。它不具备Word的完整排版能力，打开复杂Word文档可能丢失不支持的功能。记事本与写字板都是应用工具，不因系统自带就成为操作系统本身。","画图可绘制、裁剪、调整图像尺寸；Windows 10课堂中新图默认常见PNG，也支持BMP、JPEG、GIF、TIFF等格式，转换步骤见本卡前面的另存为说明。HEIC等支持受应用版本和编解码器影响，不作每台Windows 10必有功能。","标准模式做常规算术；科学模式用于科学运算；程序员模式可在二、八、十、十六进制之间查看整数并作位运算，不适合用来转换小数。需要单位换算或日期差时从菜单选择对应功能，再选单位或起止日期，不能因标准面板没显示就断言软件不支持。","Windows 10课堂中的录音机使用麦克风录音，停止后可回放、重命名或修剪；课堂图和练习对应M4A输出。开始录制前应允许麦克风访问并确认输入设备；这是声音文件，不是屏幕视频。格式以该Windows 10应用语境为准，不沿用旧Windows录音机或新版Sound Recorder的格式设置。","搜索“步骤记录器”（psr）→开始记录→重现操作，可添加文字说明→停止→检查记录后保存。它把操作步骤、截图和说明组织为报告，课堂示例保存在含MHT报告的ZIP中；不是连续录屏视频，也不是逐键保存所有输入。提交前检查截图是否含不应分享的信息。"],"boundary":"“记事本不能保存富文本格式”不能改写成“不能改字体、字形或字号”；显示变大也不等于TXT文件变大。Windows 11新版记事本和截图工具的新功能不用于替换本章的Windows 10判断口径。","id":"y2025q34","sources":[{"year":2024,"q":25,"type":"多选"},{"year":2025,"q":34,"type":"判断"},{"year":2022,"q":8,"type":"单选"}],"keys":["2024-25","2025-34","2022-8"],"related":[{"id":"merged-4","label":"文件名、扩展名、关联、只读与权限要分层判断","reason":"图像格式转换需要画图另存为等实际处理，修改扩展名本身不能完成转换。"},{"id":"merged-14","label":"GIF、PNG、JPEG、MP3、WAV与无损压缩边界","reason":"画图另存为JPEG等格式时可能丢失细节，需结合有损与无损压缩判断结果。"},{"id":"y2025q33","label":"粘贴和正常睡眠通常不会自动清空剪贴板","reason":"截图结果可能先进入剪贴板，粘贴后的结构是否保留还取决于接收应用。"}],"pointGroups":[{"title":"截图的范围、保存与标注边界","indices":[0,2]},{"title":"画图与图像格式","indices":[1,8]},{"title":"记事本与写字板按内容能力选择","indices":[3,4,5,7]},{"title":"计算器模式与日期计算","indices":[9,6]},{"title":"录音机与步骤记录器","indices":[10,11]}],"comparison":{"headers":["比较项","Windows 10传统记事本","Word 2016"],"rows":[["字体、字形、字号","可以调整整篇显示","可以为选中文字设置并保存字符格式"],["表格与图片","只保留可粘贴的文本，不保留原对象结构","文档格式可保存表格、图片等对象"],["换机后的字体外观","TXT不携带逐字字体设置，显示取决于打开程序","DOCX保存格式要求，实际显示还取决于字体等环境"]]},"pointPresentation":{"7":{"title":"记事本与写字板按内容能力选择","navigationLabel":"记事本与写字板按内容能力选择"},"8":{"title":"画图的能力与保存格式","navigationLabel":"画图的能力与保存格式"},"9":{"title":"计算器模式决定可输入什么","navigationLabel":"计算器模式决定可输入什么"},"10":{"title":"录音机先确认音频输入","navigationLabel":"录音机先确认音频输入","blocks":[{"label":"用途与结果"},{"from":"开始录制前","label":"前提与版本"}]},"11":{"title":"步骤记录器用于复现操作问题","navigationLabel":"步骤记录器用于复现操作问题","blocks":[{"label":"记录操作"},{"from":"它把操作步骤","label":"输出与限制"}]}}}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
