window.NOTE_DEMOS={"y2024q6":{"kind":"explore","title":"调度三种操作系统现场","task":"点击任务，观察决定系统设计的关键目标。","initial":"同样是操作系统，不同任务的首要约束不同。","actions":[{"label":"汽车制动控制","stage":"实时系统","result":"必须在规定时限内稳定响应。","tone":"good"},{"label":"多机统一资源池","stage":"分布式系统","result":"协调多台计算机并隐藏部分位置差异。","tone":"good"},{"label":"桌面办公与娱乐","stage":"通用操作系统","result":"兼顾交互、兼容与多任务。","tone":"good"},{"label":"安全只等于挡住陌生人","stage":"过度缩窄","result":"还包含授权、隔离、审计和完整性。","tone":"bad"}]},"y2026q7":{"kind":"explore","title":"调度器里辨认四种操作系统特征","task":"点开四个现场，观察并发、共享、虚拟和异步分别回答什么问题。","initial":"同一个“多任务”画面里可能同时出现多种特征。","actions":[{"label":"单核交替推进","stage":"A→B→A→B","result":"多个任务在一段时间内共同推进，体现并发。","tone":"good"},{"label":"两进程请求打印机","stage":"排队共享","result":"共同使用资源体现共享，必须由系统协调。","tone":"good"},{"label":"每个进程看到独立地址空间","stage":"逻辑映射","result":"用逻辑资源隐藏物理细节，体现虚拟。","tone":"good"},{"label":"完成先后每次可能不同","stage":"调度与事件影响","result":"运行次序受现场影响，体现异步。","tone":"warn"}]},"y2025q7":{"kind":"explore","title":"把作业投入批处理队列","task":"提交作业后尝试中途修改参数，观察批处理系统的取舍。","initial":"三个作业已排队等待自动运行。","actions":[{"label":"连续自动执行","stage":"吞吐量较高","result":"减少人工装卸和空闲时间。","tone":"good"},{"label":"运行中要求立刻对话","stage":"响应不及时","result":"批处理的典型短板是交互性差。","tone":"bad"},{"label":"多个作业驻留内存","stage":"可以支持多任务","result":"多道批处理能提高资源利用率。","tone":"good"},{"label":"执行打印等I/O","stage":"可以处理I/O","result":"不能把交互差误写成无法I/O。","tone":"warn"}]},"y2025q6":{"kind":"explore","title":"给操作系统做易用性改造","task":"点击改动，观察用户完成同一任务的步骤和负担。","initial":"目标：第一次使用也能找到网络设置。","actions":[{"label":"一致的图形界面","stage":"识别成本降低","result":"相似任务使用相似入口和反馈。","tone":"good"},{"label":"可搜索的帮助","stage":"遇到问题能及时定位","result":"帮助系统提高可学习性。","tone":"good"},{"label":"多语言支持","stage":"更多用户能理解界面","result":"属于可访问与易用性支持。","tone":"good"},{"label":"增加无意义的层级","stage":"路径更长、记忆负担更大","result":"复杂度不是易用性的来源。","tone":"bad"}]},"y2026q32":{"kind":"choose","title":"亲手比较正常关机与强制关机","task":"在开始菜单点“关机”；设备按钮短按会执行电源选项，持续按住才会强制断电。","options":[{"label":"开始菜单→电源→关机","result":"规范关机：结束进程、写回缓存并关闭文件系统。","tone":"good"},{"label":"长按电源键","result":"强制断电：只用于系统完全无响应，可能丢数据。","tone":"bad"},{"label":"短按电源键","result":"结果取决于电源选项，可能睡眠、关机或不执行操作。","tone":"warn"}]},"y2026q9":{"kind":"explore","title":"分别拨动读取与写入策略","task":"观察不同组策略组合对U盘操作的影响。","initial":"读取允许｜写入允许：可正常读写。","actions":[{"label":"仅拒绝写入","stage":"能看文件，不能复制新内容到U盘","result":"读写权限可以分别控制。","tone":"good"},{"label":"仅拒绝读取","stage":"不能正常打开U盘内容","result":"读取被拒绝；写入是否允许由写入策略单独控制，两者不是简单的强弱包含关系。","tone":"warn"},{"label":"同时拒绝","stage":"读取和写入均受阻","result":"适合严格管控场景，但会明显影响使用。","tone":"warn"}]},"y2024q33":{"kind":"explore","title":"跟踪卸载后的四类去向","task":"点击程序组成，观察卸载器为何不会把一切都删掉。","initial":"准备卸载“影像标注工具”。","actions":[{"label":"程序主体","stage":"通常移除","result":"可执行文件和大部分程序组件由卸载器删除。","tone":"good"},{"label":"用户病例标注","stage":"应保留","result":"用户创建的数据不应被擅自删除。","tone":"good"},{"label":"偏好与缓存","stage":"可能保留","result":"便于重装恢复，也可能成为可清理残留。","tone":"warn"},{"label":"共享运行库","stage":"按依赖决定","result":"其他程序仍使用时不能随意删除。","tone":"warn"}]},"y2025q34":{"kind":"explore","title":"操作Windows截图工具","task":"执行截图、裁剪和标注，检查它是否会自动移除水印。","initial":"屏幕图像右下角带有“示例水印”。","actions":[{"label":"矩形截图","stage":"按所选区域原样截取","result":"水印仍会被包含。","tone":"good"},{"label":"裁剪边缘","stage":"只改变保留区域","result":"不能智能重建被水印覆盖的内容。","tone":"warn"},{"label":"画笔标注","stage":"在截图上添加笔迹","result":"不是自动去水印。","tone":"warn"},{"label":"自动识别并去水印","stage":"标准工具没有此功能","result":"还涉及版权与授权边界。","tone":"bad"}]}};
